/**
 * CSV datasets for dataset challenges (content/datasets/*.csv).
 *
 * The CSVs are generated by scripts/datasets/make_datasets.py and committed.
 * They're simple: a header row, comma-separated values, no quoting; empty
 * cells are missing values.
 */
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";

export type Cell = number | string | null;

export interface Dataset {
  file: string;
  columns: string[];
  rows: Cell[][];
  /** Content hash, so tests are rebuilt when the data changes. */
  hash: string;
}

export interface Frame {
  columns: string[];
  data: Cell[][];
}

export interface DatasetSplit {
  /** Run: train on part of the training rows, predict the validation rows. */
  sample: { args: [Frame, Frame]; labels: Cell[] };
  /** Submit: train on all training rows, predict the held-out test rows. */
  hidden: { args: [Frame, Frame]; labels: Cell[] };
  preview: { columns: string[]; rows: Cell[][]; rowCount: number; trainRows: number; testRows: number };
}

const parseCell = (raw: string): Cell => {
  const v = raw.trim();
  if (v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) && /^-?\d*\.?\d+(e-?\d+)?$/i.test(v) ? n : v;
};

const cache = new Map<string, Dataset>();

export function loadDataset(dir: string, file: string): Dataset {
  const full = path.join(dir, "datasets", file);
  const hit = cache.get(full);
  if (hit) return hit;
  const text = readFileSync(full, "utf8").replace(/\r\n/g, "\n").trim();
  const [header, ...lines] = text.split("\n");
  const columns = header!.split(",").map((c) => c.trim());
  const rows = lines.map((line, i) => {
    const cells = line.split(",");
    if (cells.length !== columns.length) throw new Error(`${file} line ${i + 2}: expected ${columns.length} cells`);
    return cells.map(parseCell);
  });
  const dataset = { file, columns, rows, hash: createHash("sha256").update(text).digest("hex").slice(0, 16) };
  cache.set(full, dataset);
  return dataset;
}

/** Deterministic shuffle (mulberry32), so splits never change between builds and deploys. */
function shuffled<T>(items: T[], seed: number): T[] {
  let a = seed >>> 0;
  const rand = () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

export function splitDataset(
  dataset: Dataset,
  spec: { target: string; testFraction: number; validFraction: number; seed: number },
): DatasetSplit {
  const t = dataset.columns.indexOf(spec.target);
  if (t < 0) throw new Error(`${dataset.file}: no column "${spec.target}"`);
  const rows = shuffled(dataset.rows, spec.seed);
  const nTest = Math.round(rows.length * spec.testFraction);
  const test = rows.slice(0, nTest);
  const train = rows.slice(nTest);
  const nValid = Math.round(train.length * spec.validFraction);
  const valid = train.slice(0, nValid);
  const fit = train.slice(nValid);

  const featureColumns = dataset.columns.filter((_, i) => i !== t);
  const withTarget = (part: Cell[][]): Frame => ({ columns: dataset.columns, data: part });
  const features = (part: Cell[][]): Frame => ({
    columns: featureColumns,
    data: part.map((r) => r.filter((_, i) => i !== t)),
  });
  const labels = (part: Cell[][]) => part.map((r) => r[t] ?? null);

  return {
    sample: { args: [withTarget(fit), features(valid)], labels: labels(valid) },
    hidden: { args: [withTarget(train), features(test)], labels: labels(test) },
    preview: {
      columns: dataset.columns,
      rows: dataset.rows.slice(0, 6),
      rowCount: dataset.rows.length,
      trainRows: train.length,
      testRows: test.length,
    },
  };
}
